const select = document.getElementById("choosers");

select.addEventListener("change", () => {
  const option = select.options[select.selectedIndex];
  const group = option.parentElement;
  const key = group.label + ":" + option.value;

  if (key === "Download as:html") downloadHTML();
});

function downloadHTML() {
  const html = `
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Jackmo 👨</title>
</head>
<body>
<h1>Jackmo 👨</h1>

<script src="https://unpkg.com/react@18/umd/react.development.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
<script src="https://unpkg.com/babel-standalone@6/babel.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script>

<div id="my-apo"></div>

<script type="text/babel">
${MyApo.toString()}
ReactDOM.createRoot(document.getElementById("my-apo")).render(<MyApo />);
</script>

<p>Your project, your progress bar!</p>

<h4>How it works:</h4>
<ol>
   <li>Import Your local scratchjr file!</li>
   <li>Watch it read the contents of the file!</li>
   <li>Your final result is ready, fresh out of the unzipper!</li>
   <li>Either export it as a uncustomized, fresh, unrenamed .zip file, or export it as a playable .html file!</li>
</ol>

<footer>
  <p>Copyright © 2026 Jackmo 👨</p>
</footer>

</body>
</html>
  `;
  const blob = new Blob([html], { type: "text/html" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = "jackmo.html";
  a.click();
}